/**
 * Build the packaged app's copy of the Cumora server.
 *
 *   node scripts/build-server-bundle.mjs
 *
 * Output (all staged under build/local-dist, shipped as electron-builder
 * extraResources so it lives OUTSIDE the asar — spawnable executables and
 * WASM assets both need real files on disk):
 *
 *   build/local-dist/server.cjs                     bundled API + agent server
 *   build/local-dist/node_modules/@electric-sql/pglite/**  the embedded
 *       Postgres (WASM + contrib extensions), kept external so its runtime
 *       asset loading (postgres.wasm, pg_trgm.tar.gz) resolves from disk
 *
 * The server in embedded mode (CUMORA_DATA_DIR set) runs entirely from this
 * bundle: PGlite for Postgres, the in-process Redis replacement, no external
 * binaries, no sockets beyond the local HTTP port.
 */
import { build } from 'esbuild'
import { cp, mkdir, rm, stat } from 'node:fs/promises'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const outDir = join(root, 'build', 'local-dist')

async function exists(p) {
  try { await stat(p); return true } catch { return false }
}

async function main() {
  await rm(outDir, { recursive: true, force: true })
  await mkdir(outDir, { recursive: true })

  console.log('[bundle] esbuild server/src/index.ts → build/local-dist/server.cjs')
  const result = await build({
    entryPoints: [join(root, 'server', 'src', 'index.ts')],
    outfile: join(outDir, 'server.cjs'),
    bundle: true,
    platform: 'node',
    target: 'node20',
    format: 'cjs',
    sourcemap: false,
    logLevel: 'info',
    // `pg` is bundled (pure JS); its optional native binding is not.
    // PGlite stays external on purpose: esbuild cannot inline its .wasm /
    // .tar.gz assets, so the package is copied verbatim below.
    external: [
      'pg-native',
      '@electric-sql/pglite',
      '@electric-sql/pglite/*',
    ],
    define: {
      // Some deps branch on this at module scope; the bundle is always
      // production code (the runtime env decides embedded vs. dev behavior).
      'process.env.NODE_ENV': 'process.env.NODE_ENV',
    },
    banner: {
      js: '/* Cumora local server bundle — generated by scripts/build-server-bundle.mjs. Do not edit. */',
    },
    metafile: true,
  })

  const bytes = Object.values(result.metafile.outputs).reduce((n, o) => n + o.bytes, 0)
  console.log(`[bundle] server.cjs ≈ ${(bytes / 1024 / 1024).toFixed(1)} MB`)

  // Stage PGlite next to the bundle so `require('@electric-sql/pglite')`
  // resolves from the bundle's own directory at runtime.
  // The package's exports map hides ./package.json, so resolve by path.
  const pgliteRoot = join(root, 'node_modules', '@electric-sql', 'pglite')
  const dest = join(outDir, 'node_modules', '@electric-sql', 'pglite')
  if (!(await exists(pgliteRoot))) throw new Error('@electric-sql/pglite is not installed')
  console.log('[bundle] staging @electric-sql/pglite')
  await cp(pgliteRoot, dest, { recursive: true })

  console.log('[bundle] done →', outDir)
}

main().catch((err) => {
  console.error('[bundle] failed:', err)
  process.exit(1)
})
